CREATE TABLE public.tk_employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, pin text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT(id,name,active,created_at) ON public.tk_employees TO authenticated; GRANT ALL ON public.tk_employees TO service_role; ALTER TABLE public.tk_employees ENABLE ROW LEVEL SECURITY; CREATE POLICY tk_admin_read ON public.tk_employees FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.tk_time_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES public.tk_employees(id) ON DELETE CASCADE, clock_in timestamptz NOT NULL DEFAULT now(), clock_out timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.tk_time_entries TO authenticated; GRANT ALL ON public.tk_time_entries TO service_role; ALTER TABLE public.tk_time_entries ENABLE ROW LEVEL SECURITY; CREATE POLICY tk_admin_read ON public.tk_time_entries FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin')); CREATE INDEX tk_time_employee ON public.tk_time_entries(employee_id,clock_in DESC); CREATE INDEX tk_time_open ON public.tk_time_entries(employee_id) WHERE clock_out IS NULL;
CREATE TABLE public.tk_employee_profiles (employee_id uuid PRIMARY KEY REFERENCES public.tk_employees(id) ON DELETE CASCADE, email text, phone text, street_address text, postal_code text, city text, country text, birth_date date, birth_place text, national_number text, iban text, emergency_contact_name text, emergency_contact_phone text, job_title text, job_category text, job_tasks text, department text, employment_start_date date, contract_type text, joint_committee text, weekly_hours numeric(5,2), daily_schedule jsonb, overtime_calculation_mode text NOT NULL DEFAULT 'daily' CHECK(overtime_calculation_mode IN('daily','weekly')), employment_status text NOT NULL DEFAULT 'active' CHECK(employment_status IN('active','inactive','leave','ended')), monthly_report_enabled boolean NOT NULL DEFAULT false, split_special_hours boolean NOT NULL DEFAULT false, is_contractor boolean NOT NULL DEFAULT false, day_hourly_rate numeric(10,2), special_hourly_rate numeric(10,2), salary_advances jsonb NOT NULL DEFAULT '[]', salary_settlement_day integer NOT NULL DEFAULT 1 CHECK(salary_settlement_day BETWEEN 1 AND 31), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(weekly_hours IS NULL OR weekly_hours BETWEEN 0 AND 168), CHECK(day_hourly_rate IS NULL OR day_hourly_rate>=0), CHECK(special_hourly_rate IS NULL OR special_hourly_rate>=0));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.tk_employee_profiles TO authenticated; GRANT ALL ON public.tk_employee_profiles TO service_role; ALTER TABLE public.tk_employee_profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY tk_admin_manage ON public.tk_employee_profiles FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
