COMMENT ON TABLE public.tk_source_user_roles IS 'Historical attribution only; never grants destination permissions.';
COMMENT ON COLUMN public.tk_employees.pin IS 'Private bcrypt PIN hash. Never exposed by employee DTOs.';
CREATE FUNCTION public.tk_set_hr_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['tk_employee_profiles','tk_employee_absences','tk_employee_documents','tk_employee_notes','tk_monthly_report_jobs','tk_time_entry_requests','tk_payroll_profiles','tk_payroll_settings','tk_payroll_runs','tk_leave_requests','tk_employee_messages','tk_company_settings','tk_employment_contracts','tk_overtime_adjustments'] LOOP EXECUTE format('CREATE TRIGGER tk_updated_at BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.tk_set_hr_updated_at()',t); END LOOP; END $$;
CREATE FUNCTION public.tk_send_employee_incident(p_id uuid,p_admin uuid) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE r public.tk_employee_incidents%ROWTYPE; m uuid; body_text text; BEGIN SELECT * INTO STRICT r FROM public.tk_employee_incidents WHERE id=p_id FOR UPDATE; IF r.message_id IS NOT NULL THEN RETURN r.message_id; END IF; body_text:=CASE r.incident_type WHEN 'late' THEN 'Vaststelling op '||to_char(r.occurred_on,'DD/MM/YYYY')||': '||r.late_minutes||' minuten te laat.' WHEN 'no_show' THEN 'Vaststelling op '||to_char(r.occurred_on,'DD/MM/YYYY')||': niet komen opdagen zonder verwittiging.' ELSE 'Ziekte geregistreerd van '||to_char(r.occurred_on,'DD/MM/YYYY')||' tot en met '||to_char(r.ends_on,'DD/MM/YYYY')||'.' END; IF r.observation<>'' THEN body_text:=body_text||E'\n\n'||r.observation; END IF; INSERT INTO public.tk_employee_messages(employee_id,title,body,created_by) VALUES(r.employee_id,CASE r.incident_type WHEN 'late' THEN 'Vaststelling: te laat' WHEN 'no_show' THEN 'Vaststelling: niet opgedagen' ELSE 'Registratie: ziekte' END,body_text,p_admin) RETURNING id INTO m; UPDATE public.tk_employee_incidents SET message_id=m,sent_at=now() WHERE id=r.id; RETURN m; END $$;
REVOKE ALL ON FUNCTION public.tk_send_employee_incident(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.tk_send_employee_incident(uuid,uuid) TO service_role;
CREATE FUNCTION public.tk_record_employee_incident(p_id uuid,p_employee uuid,p_type text,p_date date,p_end date,p_minutes integer,p_observation text,p_admin uuid,p_send boolean) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN INSERT INTO public.tk_employee_incidents(id,employee_id,incident_type,occurred_on,ends_on,late_minutes,observation,created_by) VALUES(p_id,p_employee,p_type,p_date,p_end,CASE WHEN p_type='late' THEN p_minutes ELSE NULL END,p_observation,p_admin) ON CONFLICT(id) DO NOTHING; IF FOUND AND p_type='sick' THEN INSERT INTO public.tk_employee_absences(employee_id,absence_type,starts_on,ends_on,status,notes) VALUES(p_employee,'sick',p_date,p_end,'approved',p_observation); END IF; IF p_send THEN PERFORM public.tk_send_employee_incident(p_id,p_admin); END IF; RETURN p_id; END $$;
REVOKE ALL ON FUNCTION public.tk_record_employee_incident(uuid,uuid,text,date,date,integer,text,uuid,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.tk_record_employee_incident(uuid,uuid,text,date,date,integer,text,uuid,boolean) TO service_role;